from sys import stdin

def count_free_food_days(N, events):
    calendar = [False] * 366  # Array to mark days with free food
    for start, end in events:
        for day in range(start, end + 1):
            calendar[day] = True
    return sum(calendar)  # Sum up all the days with free food

# Main code to read input and print the result
if __name__ == "__main__":
    N = int(stdin.readline().strip())
    events = []
    for _ in range(N):
        s, t = map(int, stdin.readline().strip().split())
        events.append((s, t))

    result = count_free_food_days(N, events)
    print(result)
